const app = require('./app');
const supertest = require('supertest');

const request = supertest(app);

async function testRuleEndpoint() {
  try {
    // Test basic rule evaluation
    const response = await request
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      });

    console.log('Response:', response.body);

    // Test another rule
    const response2 = await request
      .post('/check')
      .send({
        rule: 'ctx.user.age >= 18 && ctx.user.name === "John"',
        context: { user: { age: 25, name: "John" } }
      });

    console.log('Response2:', response2.body);
  } catch (error) {
    console.error('Test failed:', error);
  }
}

// Install supertest if not present
const fs = require('fs');
const packageJson = JSON.parse(fs.readFileSync('./package.json'));

if (!packageJson.dependencies || !packageJson.dependencies.supertest) {
  console.log('Please install supertest: npm install supertest');
} else {
  testRuleEndpoint();
}

