const app = require('./app');
const chai = require('chai');
const chaiHttp = require('chai-http');

chai.use(chaiHttp);
const expect = chai.expect;

describe('POST /check endpoint', () => {
  it('should evaluate a simple rule correctly', async () => {
    const res = await chai.request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      });

    expect(res.status).to.equal(200);
    expect(res.body.result).to.be.true;
  });

  it('should evaluate a false rule correctly', async () => {
    const res = await chai.request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 50 }
      });

    expect(res.status).to.equal(200);
    expect(res.body.result).to.be.false;
  });

  it('should handle complex rules', async () => {
    const res = await chai.request(app)
      .post('/check')
      .send({
        rule: 'ctx.user.age >= 18 && ctx.user.country === "US"',
        context: { 
          user: { 
            age: 25, 
            country: "US" 
          } 
        }
      });

    expect(res.status).to.equal(200);
    expect(res.body.result).to.be.true;
  });

  it('should handle errors gracefully', async () => {
    const res = await chai.request(app)
      .post('/check')
      .send({
        rule: 'ctx.nonexistent.field > 100', // This will throw an error
        context: { amount: 150 }
      });

    expect(res.status).to.equal(400);
  });
});

const app = require('./app');
const http = require('http');

// Create a test server
const server = http.createServer(app);
const port = 3001; // Use a different port to avoid conflicts

server.listen(port, () => {
  console.log(`Test server running on port ${port}`);

  // Test the evalRule function directly
  const mockReq = {
    body: {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    }
  };

  try {
    // We need to access the evalRule function - let's modify app.js to export it
    console.log('Testing rule evaluation...');

    // Simulate the evalRule function
    const expr = mockReq.body.rule;
    const result = Function('ctx', `return (${expr});`)(mockReq.body.context);

    console.log('Rule:', expr);
    console.log('Context:', mockReq.body.context);
    console.log('Result:', result);

    server.close();
  } catch (error) {
    console.error('Error:', error.message);
    server.close();
  }
});

