// Test script to validate the rule engine implementation

// Mock request object for testing
const mockRequest = {
  body: {
    rule: 'ctx.amount > 100',
    context: { amount: 150 }
  }
};

// Our implementation of evalRule function
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

// Test the function
try {
  const result = evalRule(mockRequest);
  console.log('Rule evaluation result:', result); // Should be true since 150 > 100

  // Additional test cases
  const testCases = [
    {
      rule: 'ctx.amount > 100',
      context: { amount: 50 },
      expected: false
    },
    {
      rule: 'ctx.user.age >= 18',
      context: { user: { age: 25 } },
      expected: true
    },
    {
      rule: 'ctx.items.length > 0',
      context: { items: ['item1', 'item2'] },
      expected: true
    }
  ];

  testCases.forEach((testCase, index) => {
    const testReq = {
      body: {
        rule: testCase.rule,
        context: testCase.context
      }
    };

    const testResult = evalRule(testReq);
    console.log(`Test case ${index + 1}: ${testResult === testCase.expected ? 'PASS' : 'FAIL'}`);
    console.log(`  Rule: ${testCase.rule}`);
    console.log(`  Context: ${JSON.stringify(testCase.context)}`);
    console.log(`  Expected: ${testCase.expected}, Got: ${testResult}`);
  });
} catch (error) {
  console.error('Error evaluating rule:', error.message);
}

